code:
// 参数化基线：64QAM max-log LLR（v4：abs 距离 + (d1-d0)(d1+d0)，朴素）
// 2σ²归一 Q8.8 与 golden 同口径；距离差 = m1 - m0（bit=0 证据强 → 正 LLR）
module top (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire signed [15:0] i_in,
    input  wire signed [15:0] q_in,
    output reg                out_valid,
    input  wire               out_ready,
    output reg signed [15:0] llr0, output reg signed [15:0] llr1, output reg signed [15:0] llr2, output reg signed [15:0] llr3, output reg signed [15:0] llr4, output reg signed [15:0] llr5
);
    // EVOLVE-BLOCK-START
    function [15:0] minu16;
        input [15:0] a;
        input [15:0] b;
        begin
            minu16 = (a < b) ? a : b;
        end
    endfunction
    // 输入 16b Q8.8 符号扩展到 17b；|星座点|<=28672 且 |输入|<=32768，故 |y-A|<=61440 适用 16b 无符号
    wire signed [16:0] yi = {i_in[15], i_in};
    wire signed [16:0] yq = {q_in[15], q_in};
    wire signed [16:0] A0 = 17'sd4096;
    wire signed [16:0] A1 = 17'sd12288;
    wire signed [16:0] A2 = 17'sd28672;
    wire signed [16:0] A3 = 17'sd20480;
    wire signed [16:0] A4 = -17'sd20480;
    wire signed [16:0] A5 = -17'sd28672;
    wire signed [16:0] A6 = -17'sd12288;
    wire signed [16:0] A7 = -17'sd4096;
    wire signed [16:0] dyi0 = yi - A0;  wire signed [16:0] ndyi0 = -dyi0;
    wire signed [16:0] dyi1 = yi - A1;  wire signed [16:0] ndyi1 = -dyi1;
    wire signed [16:0] dyi2 = yi - A2;  wire signed [16:0] ndyi2 = -dyi2;
    wire signed [16:0] dyi3 = yi - A3;  wire signed [16:0] ndyi3 = -dyi3;
    wire signed [16:0] dyi4 = yi - A4;  wire signed [16:0] ndyi4 = -dyi4;
    wire signed [16:0] dyi5 = yi - A5;  wire signed [16:0] ndyi5 = -dyi5;
    wire signed [16:0] dyi6 = yi - A6;  wire signed [16:0] ndyi6 = -dyi6;
    wire signed [16:0] dyi7 = yi - A7;  wire signed [16:0] ndyi7 = -dyi7;
    wire [15:0] adi0 = dyi0[16] ? ndyi0[15:0] : dyi0[15:0];
    wire [15:0] adi1 = dyi1[16] ? ndyi1[15:0] : dyi1[15:0];
    wire [15:0] adi2 = dyi2[16] ? ndyi2[15:0] : dyi2[15:0];
    wire [15:0] adi3 = dyi3[16] ? ndyi3[15:0] : dyi3[15:0];
    wire [15:0] adi4 = dyi4[16] ? ndyi4[15:0] : dyi4[15:0];
    wire [15:0] adi5 = dyi5[16] ? ndyi5[15:0] : dyi5[15:0];
    wire [15:0] adi6 = dyi6[16] ? ndyi6[15:0] : dyi6[15:0];
    wire [15:0] adi7 = dyi7[16] ? ndyi7[15:0] : dyi7[15:0];
    wire signed [16:0] dyq0 = yq - A0;  wire signed [16:0] ndyq0 = -dyq0;
    wire signed [16:0] dyq1 = yq - A1;  wire signed [16:0] ndyq1 = -dyq1;
    wire signed [16:0] dyq2 = yq - A2;  wire signed [16:0] ndyq2 = -dyq2;
    wire signed [16:0] dyq3 = yq - A3;  wire signed [16:0] ndyq3 = -dyq3;
    wire signed [16:0] dyq4 = yq - A4;  wire signed [16:0] ndyq4 = -dyq4;
    wire signed [16:0] dyq5 = yq - A5;  wire signed [16:0] ndyq5 = -dyq5;
    wire signed [16:0] dyq6 = yq - A6;  wire signed [16:0] ndyq6 = -dyq6;
    wire signed [16:0] dyq7 = yq - A7;  wire signed [16:0] ndyq7 = -dyq7;
    wire [15:0] adq0 = dyq0[16] ? ndyq0[15:0] : dyq0[15:0];
    wire [15:0] adq1 = dyq1[16] ? ndyq1[15:0] : dyq1[15:0];
    wire [15:0] adq2 = dyq2[16] ? ndyq2[15:0] : dyq2[15:0];
    wire [15:0] adq3 = dyq3[16] ? ndyq3[15:0] : dyq3[15:0];
    wire [15:0] adq4 = dyq4[16] ? ndyq4[15:0] : dyq4[15:0];
    wire [15:0] adq5 = dyq5[16] ? ndyq5[15:0] : dyq5[15:0];
    wire [15:0] adq6 = dyq6[16] ? ndyq6[15:0] : dyq6[15:0];
    wire [15:0] adq7 = dyq7[16] ? ndyq7[15:0] : dyq7[15:0];
    // I 轴 bit0（S0=[0, 1, 2, 3] S1=[4, 5, 6, 7]）
    wire [15:0] d0_i0 = minu16(minu16(adi0, adi1), minu16(adi2, adi3));
    wire [15:0] d1_i0 = minu16(minu16(adi4, adi5), minu16(adi6, adi7));
    wire signed [16:0] dd_i0 = $signed({1'b0, d1_i0}) - $signed({1'b0, d0_i0});
    wire signed [17:0] ds_i0 = $signed({2'b0, d1_i0}) + $signed({2'b0, d0_i0});
    wire signed [34:0] pd_i0 = dd_i0 * ds_i0;
    wire signed [18:0] lq_i0 = $signed(pd_i0[34:16]) + $signed({18'b0, pd_i0[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_i0 = (lq_i0 > 19'sd32767) ? 16'sd32767 : (lq_i0 < -19'sd32768) ? -16'sd32768 : lq_i0[15:0];
    // Q 轴 bit0（S0=[0, 1, 2, 3] S1=[4, 5, 6, 7]）
    wire [15:0] d0_q0 = minu16(minu16(adq0, adq1), minu16(adq2, adq3));
    wire [15:0] d1_q0 = minu16(minu16(adq4, adq5), minu16(adq6, adq7));
    wire signed [16:0] dd_q0 = $signed({1'b0, d1_q0}) - $signed({1'b0, d0_q0});
    wire signed [17:0] ds_q0 = $signed({2'b0, d1_q0}) + $signed({2'b0, d0_q0});
    wire signed [34:0] pd_q0 = dd_q0 * ds_q0;
    wire signed [18:0] lq_q0 = $signed(pd_q0[34:16]) + $signed({18'b0, pd_q0[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_q0 = (lq_q0 > 19'sd32767) ? 16'sd32767 : (lq_q0 < -19'sd32768) ? -16'sd32768 : lq_q0[15:0];
    // I 轴 bit1（S0=[0, 1, 4, 5] S1=[2, 3, 6, 7]）
    wire [15:0] d0_i1 = minu16(minu16(adi0, adi1), minu16(adi4, adi5));
    wire [15:0] d1_i1 = minu16(minu16(adi2, adi3), minu16(adi6, adi7));
    wire signed [16:0] dd_i1 = $signed({1'b0, d1_i1}) - $signed({1'b0, d0_i1});
    wire signed [17:0] ds_i1 = $signed({2'b0, d1_i1}) + $signed({2'b0, d0_i1});
    wire signed [34:0] pd_i1 = dd_i1 * ds_i1;
    wire signed [18:0] lq_i1 = $signed(pd_i1[34:16]) + $signed({18'b0, pd_i1[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_i1 = (lq_i1 > 19'sd32767) ? 16'sd32767 : (lq_i1 < -19'sd32768) ? -16'sd32768 : lq_i1[15:0];
    // Q 轴 bit1（S0=[0, 1, 4, 5] S1=[2, 3, 6, 7]）
    wire [15:0] d0_q1 = minu16(minu16(adq0, adq1), minu16(adq4, adq5));
    wire [15:0] d1_q1 = minu16(minu16(adq2, adq3), minu16(adq6, adq7));
    wire signed [16:0] dd_q1 = $signed({1'b0, d1_q1}) - $signed({1'b0, d0_q1});
    wire signed [17:0] ds_q1 = $signed({2'b0, d1_q1}) + $signed({2'b0, d0_q1});
    wire signed [34:0] pd_q1 = dd_q1 * ds_q1;
    wire signed [18:0] lq_q1 = $signed(pd_q1[34:16]) + $signed({18'b0, pd_q1[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_q1 = (lq_q1 > 19'sd32767) ? 16'sd32767 : (lq_q1 < -19'sd32768) ? -16'sd32768 : lq_q1[15:0];
    // I 轴 bit2（S0=[0, 2, 4, 6] S1=[1, 3, 5, 7]）
    wire [15:0] d0_i2 = minu16(minu16(adi0, adi2), minu16(adi4, adi6));
    wire [15:0] d1_i2 = minu16(minu16(adi1, adi3), minu16(adi5, adi7));
    wire signed [16:0] dd_i2 = $signed({1'b0, d1_i2}) - $signed({1'b0, d0_i2});
    wire signed [17:0] ds_i2 = $signed({2'b0, d1_i2}) + $signed({2'b0, d0_i2});
    wire signed [34:0] pd_i2 = dd_i2 * ds_i2;
    wire signed [18:0] lq_i2 = $signed(pd_i2[34:16]) + $signed({18'b0, pd_i2[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_i2 = (lq_i2 > 19'sd32767) ? 16'sd32767 : (lq_i2 < -19'sd32768) ? -16'sd32768 : lq_i2[15:0];
    // Q 轴 bit2（S0=[0, 2, 4, 6] S1=[1, 3, 5, 7]）
    wire [15:0] d0_q2 = minu16(minu16(adq0, adq2), minu16(adq4, adq6));
    wire [15:0] d1_q2 = minu16(minu16(adq1, adq3), minu16(adq5, adq7));
    wire signed [16:0] dd_q2 = $signed({1'b0, d1_q2}) - $signed({1'b0, d0_q2});
    wire signed [17:0] ds_q2 = $signed({2'b0, d1_q2}) + $signed({2'b0, d0_q2});
    wire signed [34:0] pd_q2 = dd_q2 * ds_q2;
    wire signed [18:0] lq_q2 = $signed(pd_q2[34:16]) + $signed({18'b0, pd_q2[15]});  // 四舍五入 Q8.24 → Q8.8
    wire signed [15:0] llrv_q2 = (lq_q2 > 19'sd32767) ? 16'sd32767 : (lq_q2 < -19'sd32768) ? -16'sd32768 : lq_q2[15:0];

    assign in_ready = !out_valid || out_ready;
    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            llr0 <= 16'sd0;
            llr1 <= 16'sd0;
            llr2 <= 16'sd0;
            llr3 <= 16'sd0;
            llr4 <= 16'sd0;
            llr5 <= 16'sd0;
        end else begin
            if (out_valid && out_ready) out_valid <= 1'b0;
            if (in_valid && in_ready) begin
                llr0 <= llrv_i0;
                llr1 <= llrv_i1;
                llr2 <= llrv_i2;
                llr3 <= llrv_q0;
                llr4 <= llrv_q1;
                llr5 <= llrv_q2;
                out_valid <= 1'b1;
            end
        end
    end
    // EVOLVE-BLOCK-END
endmodule

